<script>
(function(){
 const input=document.getElementById('searchInput');const body=document.getElementById('tableBody');const pages=document.getElementById('paginationLinks');const status=document.getElementById('oysStudentSearchStatus');if(!input||!body||!pages)return;
 let controller=null;let requestNumber=0;let timeout;
 function load(url){if(controller)controller.abort();controller=new AbortController();const seq=++requestNumber;status.textContent='Searching students…';fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},signal:controller.signal}).then(response=>{if(!response.ok)throw new Error('Search unavailable');return response.json();}).then(data=>{if(seq!==requestNumber)return;body.innerHTML=data.rows||'';pages.innerHTML=data.pagination||'';status.textContent=input.value.trim()?'Showing search results':'Browse students or type to search all records.';}).catch(error=>{if(error.name==='AbortError')return;status.textContent='Unable to load results. Please try again.';});}
 input.addEventListener('input',function(){clearTimeout(timeout);const query=this.value.trim();timeout=setTimeout(()=>{load('/admin/search-students?query='+encodeURIComponent(query));},250);});
 pages.addEventListener('click',function(event){const link=event.target.closest('a[href]');if(!link||!input.value.trim())return;event.preventDefault();try{const url=new URL(link.href,window.location.href);url.searchParams.set('query',input.value.trim());load(url.toString());}catch(error){window.location.href=link.href;}});
})();
</script>
